UPDATE `fa_cms_layout_component` SET `title`='关于金亚包装',`content`='郑州金亚包装有限公司是一家集设计、印刷、制作于一体，专注不干胶标签、包装袋、无版印刷、彩盒包装解决方案的生产厂家。始终秉持"诚信、共赢、创新"的经营理念，并致力于实践"诚信立基、创新引领、严谨求实、守时高效"的精神风貌与工作作风，为客户提供卓越的产品与服务，共创美好未来。',`status`='normal',`deletetime`=NULL,`updatetime`=@html_now WHERE `component_key`='layout.footer.company';
