INSERT INTO `fa_cms_home_section`
(`section_key`,`section_name`,`title`,`mobile_title`,`subtitle`,`mobile_subtitle`,`content`,`background_image`,`mobile_background_image`,`more_text`,`more_url`,`pc_visible`,`mobile_visible`,`config_json`,`source_key`,`edited_by_admin`,`weigh`,`status`,`createtime`,`updatetime`)
VALUES('about','公司简介','关于金亚','关于金亚','ABOUT US','ABOUT US','郑州金亚包装有限公司是一家集设计、印刷、制作于一体的一站式包装生产厂家，公司深耕细作包装领域，专注于农化、食品、中药类、保健类包装定制。

公司汇聚了知名美院设计师及经验丰富的印刷团队，配备5台高精度印刷机、8台高速复合机、10台模切机及多台分条制袋机等自动化生产设备，日产标签100万张，包装袋80万+，纸盒20万。以丰富的工作经验、严谨的工作态度和全面的服务体系，为每一款包装的品质护航。

企业坚守诚信、共赢、创新经营理念，守时高效，一站式配套省心省力，诚邀各界新老客户咨询洽谈，携手共创行业发展新机遇。','','','','/page/contact',1,1,'{"social_text_1":"微信加好友","social_url_1":"/page/contact","social_text_2":"关注金亚包装视频号","social_url_2":"/page/contact","media_items":[{"title":"设计团队办公场景","image":"/assets/jinya/img/about-1.jpg","video_url":"","url":""},{"title":"高速印刷生产线","image":"/assets/jinya/img/about-2.jpg","video_url":"","url":""},{"title":"成品展示陈列室","image":"/assets/jinya/img/about-3.jpg","video_url":"","url":""},{"title":"印刷设备操作","image":"/assets/jinya/img/about-4.jpg","video_url":"","url":""}]}','html-baseline:home:about',0,900,'normal',@html_now,@html_now)
ON DUPLICATE KEY UPDATE
`title`=IF(`edited_by_admin`=0,VALUES(`title`),`title`),`mobile_title`=IF(`edited_by_admin`=0,VALUES(`mobile_title`),`mobile_title`),
`subtitle`=IF(`edited_by_admin`=0,VALUES(`subtitle`),`subtitle`),`mobile_subtitle`=IF(`edited_by_admin`=0,VALUES(`mobile_subtitle`),`mobile_subtitle`),
`content`=IF(`edited_by_admin`=0,VALUES(`content`),`content`),`background_image`=IF(`edited_by_admin`=0,VALUES(`background_image`),`background_image`),
`mobile_background_image`=IF(`edited_by_admin`=0,VALUES(`mobile_background_image`),`mobile_background_image`),`more_text`=IF(`edited_by_admin`=0,VALUES(`more_text`),`more_text`),
`more_url`=IF(`edited_by_admin`=0,VALUES(`more_url`),`more_url`),`config_json`=IF(`edited_by_admin`=0,VALUES(`config_json`),`config_json`),
`weigh`=IF(`edited_by_admin`=0,VALUES(`weigh`),`weigh`),`status`=IF(`edited_by_admin`=0,'normal',`status`),`deletetime`=IF(`edited_by_admin`=0,NULL,`deletetime`),`updatetime`=@html_now;
