INSERT INTO `fa_cms_home_section`
(`section_key`,`section_name`,`title`,`mobile_title`,`subtitle`,`mobile_subtitle`,`content`,`background_image`,`mobile_background_image`,`more_text`,`more_url`,`pc_visible`,`mobile_visible`,`config_json`,`source_key`,`edited_by_admin`,`weigh`,`status`,`createtime`,`updatetime`)
VALUES('workshop','生产车间','生产车间','生产车间','一人一份责任，全员一份口碑   严谨务实，高效协作','一人一份责任，全员一份口碑   严谨务实，高效协作','','','','','',1,1,'{"items":[{"title":"高速高精度印刷机 适配大小定单","text":"一体化集成，工艺一步成型，材质兼容广，适配多品类标签，稳定高效，自动化控损提产能","image":"/assets/jinya/img/workshop-1.jpg","icon":"","url":"","subtitle":"","mobile_image":"","pc_visible":"1","mobile_visible":"1"},{"title":"引进进口柔印十色高速机","text":"十色同步印刷，色彩还原精度拉满，高速稳定量产，降本增效优势显著","image":"/assets/jinya/img/workshop-2.jpg","icon":"","url":"","subtitle":"","mobile_image":"","pc_visible":"1","mobile_visible":"1"},{"title":"自动化，高精度 大小定单快捷 工艺齐全","text":"各种材质，大小定制，食品类、农化类、农肥类、宠物类、日化类等标签颜色高度还原、快速出货。","image":"/assets/jinya/img/workshop-3.jpg","icon":"","url":"","subtitle":"","mobile_image":"","pc_visible":"1","mobile_visible":"1"},{"title":"一线品牌制袋机 快速稳定高效","text":"高速精准印刷，色彩饱满通透，制袋运行平稳，生产提质增效，对各类包装袋型和材质，精准适配，快速出货，高效服务。","image":"/assets/jinya/img/workshop-4.jpg","icon":"","url":"","subtitle":"","mobile_image":"","pc_visible":"1","mobile_visible":"1"},{"title":"高速复合机 制袋机 分切机","text":"兼容食品、农资等各种袋型，三边封，四边封，站立袋，拉链袋，八边封、异形袋吸嘴袋等。不同行业包装标配。","image":"/assets/jinya/img/workshop-5.jpg","icon":"","url":"","subtitle":"","mobile_image":"","pc_visible":"1","mobile_visible":"1"},{"title":"个性化定制 品类多样","text":"包装一站式个性化定制，涵盖食品、中药类、保健类、农资、日化等各类包装袋与标签，尺寸、色彩、工艺均可按需调整，为品牌打造专属辨识度包装。","image":"/assets/jinya/img/workshop-6.jpg","icon":"","url":"","subtitle":"","mobile_image":"","pc_visible":"1","mobile_visible":"1"}]}','html-baseline:home:workshop',0,600,'normal',@html_now,@html_now)
ON DUPLICATE KEY UPDATE
`title`=IF(`edited_by_admin`=0,VALUES(`title`),`title`),`mobile_title`=IF(`edited_by_admin`=0,VALUES(`mobile_title`),`mobile_title`),
