UPDATE `fa_cms_page_content_block` SET `block_type`='label_section',`title`='',`subtitle`='',`content`='',`image`='',`mobile_image`='',`link_text`='',`link_url`='',`extra_json`='{"items":[{"title":"铜版纸不干胶","text":"特点：表面光滑细腻，印刷色彩流畅，彩色印刷还原性强，能满足您对印刷品质的高要求\\n优点：性价比高，成本低，印刷适应性广，适用于各行业，是当前市场常用的标签\\n缺点：不防水、不防油、易撕裂。过膜后表面可防水防油\\n用途：农肥、农药、药品、香油杂粮、食品、酒水、电气等\\n可做工艺：覆膜、专色和彩色印刷、烫金、烫银、UV凹凸、逆向等\\n形状：圆形、圆角、直角等不规则模切","image":"/assets/jinya/img/label-copper.jpg","subtitle":"","badge":"","group":"normal","url":"","value":"","mobile_title":"","mobile_text":"","mobile_image":"","mobile_subtitle":"","mobile_badge":"","mobile_url":"","pc_visible":1,"mobile_visible":1,"image_top":"/assets/jinya/img/craft-uv.jpg","image_bottom":"/assets/jinya/img/label-pe-clear.jpg"},{"title":"珠光膜/PVC/合成纸不干胶","text":"特点：自带细腻珠光柔光质感；防水防油，韧性强不易撕烂；耐酒精、耐油污、耐高低温。\\n用途：食品、农肥、保健品、中药、美妆护肤、高端食品礼盒等。\\n印刷工艺：柔印、覆哑膜、烫金银、凹凸压纹、模切卷装。","image":"/assets/jinya/img/label-pvc.jpg","subtitle":"","badge":"","group":"normal","url":"","value":"","mobile_title":"","mobile_text":"","mobile_image":"","mobile_subtitle":"","mobile_badge":"","mobile_url":"","pc_visible":1,"mobile_visible":1,"image_top":"/assets/jinya/img/craft-gloss.jpg","image_bottom":"/assets/jinya/img/craft-matte.jpg"},{"title":"亮银/哑银/合成银不干胶","text":"特点：耐高温，防水防油污，防刮以及防化学腐蚀\\n优点：不透光，有特别的金属质感\\n用途：食品、农化、中药、日化等\\n工艺：UV逆向、磨砂、光膜、哑膜","image":"/assets/jinya/img/label-print-3.jpg","subtitle":"","badge":"","group":"reverse","url":"","value":"","mobile_title":"","mobile_text":"","mobile_image":"","mobile_subtitle":"","mobile_badge":"","mobile_url":"","pc_visible":1,"mobile_visible":1,"image_top":"/assets/jinya/img/label-silver-rev.jpg","image_bottom":"/assets/jinya/img/label-bright-silver.jpg"},{"title":"镭射不干胶","text":"特点：光感特性能呈现幻彩感，拥有动态炫彩效果和特殊金属质感，防水防油防刮和抗腐蚀。\\n工艺：白色+彩色印刷、光膜、光油、UV\\n用途：食品、农资、干果、保健品、中药、宠物等高端行业","image":"/assets/jinya/img/label-print-1.jpg","subtitle":"","badge":"","group":"reverse","url":"","value":"","mobile_title":"","mobile_text":"","mobile_image":"","mobile_subtitle":"","mobile_badge":"","mobile_url":"","pc_visible":1,"mobile_visible":1,"image_top":"/assets/jinya/img/label-laser.jpg","image_bottom":"/assets/jinya/img/label-print-2.jpg"}]}',`pc_visible`=1,`mobile_visible`=1,`weigh`=800,`status`='normal',`deletetime`=NULL,`updatetime`=@html_now WHERE `page_id`=@page_id AND `block_key`='label_capability' AND `edited_by_admin`=0;
