UPDATE `fa_cms_page_content_block` SET `block_type`='about_section',`title`='金亚包装，专注做好一件事：打造高品质包装',`subtitle`='',`content`='',`image`='',`mobile_image`='',`link_text`='',`link_url`='',`extra_json`='{"items":[{"title":"质量保证 · 用心印好包装","text":"我们脚踏实地深耕包装印刷，专注把控全流程，从设计到印刷，深入遵循各项行业规范。我们坚信，品质是企业的生命线，更是商家立足市场的根本。坚持严守工艺标准、打磨每一处细节，以扎实可靠的成品赢得客户信赖。","image":"/assets/jinya/img/about-block-1.jpg","subtitle":"","badge":"","group":"","url":"","value":"","mobile_title":"","mobile_text":"","mobile_image":"","mobile_subtitle":"","mobile_badge":"","mobile_url":"","pc_visible":1,"mobile_visible":1},{"title":"增效工艺，保障细节清晰呈现。","text":"从前期设计落地到印刷成品，持续优化整套生产流程。依托成熟增效工艺，在提升交付效率的同时，不放过任何一处细微瑕疵。","image":"/assets/jinya/img/about-block-2.jpg","subtitle":"","badge":"","group":"reverse","url":"","value":"","mobile_title":"","mobile_text":"","mobile_image":"","mobile_subtitle":"","mobile_badge":"","mobile_url":"","pc_visible":1,"mobile_visible":1},{"title":"快捷高效，直击客户核心需求","text":"从方案对接、样品打样到成品出货，理顺全流程工序，减少不必要等待。依托成熟印刷工艺与灵活生产模式，兼顾效率与品质。","image":"/assets/jinya/img/about-block-3.jpg","subtitle":"","badge":"","group":"","url":"","value":"","mobile_title":"","mobile_text":"","mobile_image":"","mobile_subtitle":"","mobile_badge":"","mobile_url":"","pc_visible":1,"mobile_visible":1},{"title":"品质稳定｜灵活定制，赋能伙伴发展","text":"稳定品质是长久合作的根基，从设计到印刷严守行业规范，层层品控。同时支持多样化灵活定制，兼容大小批量订单。","image":"/assets/jinya/img/workshop-2.jpg","subtitle":"","badge":"","group":"reverse","url":"","value":"","mobile_title":"","mobile_text":"","mobile_image":"","mobile_subtitle":"","mobile_badge":"","mobile_url":"","pc_visible":1,"mobile_visible":1}]}',`pc_visible`=1,`mobile_visible`=1,`weigh`=300,`status`='normal',`deletetime`=NULL,`updatetime`=@html_now WHERE `page_id`=@page_id AND `block_key`='about_values' AND `edited_by_admin`=0;
