UPDATE `fa_cms_article_category` SET `status`='hidden' WHERE `slug`<>'html-news';
INSERT INTO `fa_cms_article_category`(`parent_id`,`name`,`slug`,`description`,`weigh`,`status`,`createtime`,`updatetime`) VALUES(0,'新闻咨询','html-news','金亚包装新闻咨询',1000,'normal',@html_now,@html_now)
ON DUPLICATE KEY UPDATE `name`='新闻咨询',`status`='normal',`deletetime`=NULL;
SET @news_cat := (SELECT `id` FROM `fa_cms_article_category` WHERE `slug`='html-news' LIMIT 1);
UPDATE `fa_cms_article` SET `status`='hidden' WHERE `edited_by_admin`=0 AND `source_key` NOT LIKE 'html-baseline:news:%';

INSERT INTO `fa_cms_article`(`category_id`,`title`,`slug`,`cover_image`,`mobile_cover_image`,`summary`,`content`,`source`,`tags`,`is_recommend`,`weigh`,`status`,`publish_time`,`source_key`,`edited_by_admin`,`createtime`,`updatetime`)
VALUES(@news_cat,'为什么大家都青睐合成标签？选金亚包装合成标签','html-synthetic-label-20260724','/assets/jinya/img/news-1.jpg','/assets/jinya/img/news-1.jpg','印刷色彩高度还原，成品质感细腻高级。搭配可移胶，轻松揭除、不留残胶，不伤产品表面。使用便捷，出货快捷，材质柔韧耐用，防水抗撕，适配多种产品场景，满足多样化贴标需求，是品牌标签优选方案。','随着产品包装越来越重视品牌识别度和终端展示效果，标签不仅承担产品信息传递的功能，也逐渐成为包装视觉的重要组成部分。合成标签凭借耐用、整洁、适配范围广等特点，被应用在多种包装场景中。

## 合成标签为什么更受欢迎？

在实际使用中，合成材料具有较好的柔韧性和稳定性，配合合适的印刷与表面工艺，可以获得清晰、细腻的图文效果。

## 可移胶使用更灵活

针对需要临时标识、后续揭除或对产品表面有保护要求的场景，可选择可移胶方案。

## 从设计到生产，兼顾不同订单需求

金亚包装围绕标签的材质、尺寸、胶水、印刷和后道工艺进行组合，根据产品使用环境与包装方式提供对应方案。','金亚包装','合成标签,不干胶标签',1,100,'published',UNIX_TIMESTAMP('2026-07-24 12:00:00'),'html-baseline:news:html-synthetic-label-20260724',0,@html_now,@html_now)
ON DUPLICATE KEY UPDATE `cover_image`=IF(`edited_by_admin`=0,VALUES(`cover_image`),`cover_image`),`mobile_cover_image`=IF(`edited_by_admin`=0,VALUES(`mobile_cover_image`),`mobile_cover_image`),`summary`=IF(`edited_by_admin`=0,VALUES(`summary`),`summary`),`content`=IF(`edited_by_admin`=0,VALUES(`content`),`content`),`status`=IF(`edited_by_admin`=0,'published',`status`),`publish_time`=IF(`edited_by_admin`=0,VALUES(`publish_time`),`publish_time`),`deletetime`=IF(`edited_by_admin`=0,NULL,`deletetime`);
